import * as React from "react"
import { Link } from "gatsby"
import Header from "../../components/Header"
import Seo from "../../components/Seo"
import LogsAdmin from "../../components/admin/LogsAdmin"
import * as s from "../../components/admin/Admin.module.css"

/**
 * The action log, on its own page — FCS-099. The list gates itself: it asks
 * the server, and an account without an admin row is told so rather than
 * shown an empty table.
 *
 * `?user=<id>` narrows it to one account. It is read after mount, not during
 * the build, because a static page has no query string to read.
 */
const LogsPage = () => {
  const [user, setUser] = React.useState(null)

  React.useEffect(() => {
    const id = new URLSearchParams(window.location.search).get("user") || ""
    setUser(/^[0-9a-f-]{36}$/i.test(id) ? id : "")
  }, [])

  return (
    <>
      <Header />
      <main className={s.page} data-print="hide">
        <div className="container">
          <div className={s.head}>
            <h1 className={s.title}>Activity log</h1>
          </div>
          <p className={s.lead}>
            What people did and whether it worked: account, action, time, success or failure.
            Newest first.
          </p>
          <div className={s.card}>{user === null ? null : <LogsAdmin user={user} />}</div>
          <p className={s.lead}>
            <Link to="/admin/">Back to Admin</Link>
          </p>
        </div>
      </main>
    </>
  )
}

export const Head = () => <Seo title="Activity log" description="Internal tools." noindex />

export default LogsPage
